// T1090.001 Internal Proxy - port forward or tunnel set up: netsh portproxy (command or registry),
// ssh/plink port forwarding, known tunnel tools (chisel, ligolo etc.)
// Runs hourly; window ends 10 minutes ago to allow for Defender ingestion delay.
let startTime = ago(70m);
let endTime   = ago(10m);
// Testing: uncomment, set dates (UTC), comment out the two lines above
// let startTime = datetime(2026-10-01 14:00:00);
// let endTime   = datetime(2026-10-01 17:00:00);
let tunnelToolFiles = dynamic(["chisel.exe", "frpc.exe", "frps.exe", "gost.exe", "socat.exe", "lcx.exe",
    "ew.exe", "iox.exe", "npc.exe", "3proxy.exe"]);
// Distinctive tool names, matched against the executable name only (any OS). Matching the whole command
// line caught ls of Apache's mod_proxy_wstunnel and a zsh __CHISEL_ environment marker.
let tunnelToolNameRegex = @'(chisel|ligolo|revsocks|rpivot|3proxy|htran|stowaway|wstunnel|earthworm|rsocx)';
// chisel client reverse-forward syntax (R:socks, R:8080:host:80), for renamed binaries. Case-sensitive.
let chiselSyntaxRegex = @'\sR:(socks|[\d.]+:)';
// netsh interface portproxy add/set (show and delete are ignored)
let portProxyRegex = @'(?i)\bportproxy\b.*\b(add|set)\b';
// ssh/plink -R, -L or -D followed by a port. Case-sensitive: lower-case -l is the login name.
let sshForwardRegex = @'\s-[A-Za-z]*[RLD]\s*(\[|\*:|[\w.-]+:)?\d+';
// Accounts allowed to use ssh forwarding or portproxy (e.g. developers using WSL), from the watchlist
let tunnelAccounts =
    _GetWatchlist('DetectionExclusions')
    | where Rule == "T1090.001" and ExceptionType == "TunnelAccount"
    | project AccountName = tolower(tostring(SearchKey));
let tunnelProcs =
    DeviceProcessEvents
    | where TimeGenerated between (startTime .. endTime)
    | where ActionType == "ProcessCreated"
    | extend Proc = tolower(FileName), Parent = tolower(InitiatingProcessFileName)
    | extend Kind = case(
            Proc in (tunnelToolFiles) or Proc matches regex tunnelToolNameRegex
                or ProcessCommandLine matches regex chiselSyntaxRegex,
                "Known tunnel or proxy tool",
            Proc == "netsh.exe" and ProcessCommandLine matches regex portProxyRegex,
                "netsh portproxy rule added",
            Proc in ("ssh.exe", "plink.exe")
                and (ProcessCommandLine matches regex sshForwardRegex
                     or ProcessCommandLine matches regex @'(?i)(remote|local|dynamic)forward'),
                "SSH port forwarding",
            "")
    | where isnotempty(Kind)
    | project TimeGenerated, DeviceId, DeviceName, AccountDomain, AccountName,
              Command = ProcessCommandLine, Proc, Parent, Kind;
// The portproxy rule itself - also catches abbreviated netsh syntax (netsh i p a v ...)
let portProxyReg =
    DeviceRegistryEvents
    | where TimeGenerated between (startTime .. endTime)
    | where ActionType == "RegistryValueSet"
    | where RegistryKey contains @"\Services\PortProxy\"
    | project TimeGenerated, DeviceId, DeviceName,
              AccountDomain = InitiatingProcessAccountDomain, AccountName = InitiatingProcessAccountName,
              Command = strcat("Registry: ", RegistryKey, " | ", RegistryValueName, " -> ", RegistryValueData),
              Proc = tolower(InitiatingProcessFileName), Parent = tolower(InitiatingProcessParentFileName),
              Kind = "PortProxy registry value set";
let tunnelSetup =
    union tunnelProcs, portProxyReg
    // watchlisted accounts, unless a known tool is involved
    | where not(AccountName in~ (tunnelAccounts) and Kind != "Known tunnel or proxy tool")
    | extend Targets = extract_all(@'(\d{1,3}(?:\.\d{1,3}){3})', Command)
    | summarize StartTime       = min(TimeGenerated),
                EndTime         = max(TimeGenerated),
                Executions      = count(),
                Reasons         = make_set(Kind, 5),
                SampleTargets   = make_set(Targets, 25),
                SampleCommands  = make_set(Command, 10),
                Processes       = make_set(Proc, 10),
                ParentProcesses = make_set(Parent, 10)
        by DeviceId, DeviceName, AccountDomain, AccountName
    | extend DistinctTargets = array_length(SampleTargets)
    | extend Severity = iff(array_length(Reasons) == 1 and tostring(Reasons[0]) == "SSH port forwarding",
                            "Medium", "High"),
             DetectionBranch = "Port forward or tunnel set up";
tunnelSetup
| extend ReasonsText   = strcat_array(Reasons, "; "),
         SampleCommand = tostring(SampleCommands[0])
| project StartTime, EndTime, DeviceName, DeviceId, AccountDomain, AccountName,
          DetectionBranch, Severity, ReasonsText, DistinctTargets, SampleTargets,
          Processes, ParentProcesses, SampleCommand, SampleCommands, Executions
| order by StartTime desc

// T1090.001 Internal Proxy - proxy process: one process relaying traffic. It accepts connections from
// internal hosts and connects onward, or holds an internet connection while reaching several internal endpoints.
// Runs hourly; query period 14 days (counts how common a process is). Window ends 10 minutes ago
// to allow for Defender ingestion delay.
let startTime = ago(70m);
let endTime   = ago(10m);
// Testing: uncomment, set dates (UTC), comment out the two lines above
// let startTime = datetime(2026-10-01 14:00:00);
// let endTime   = datetime(2026-10-01 17:00:00);
let baselinePeriod = 13d;          // must fit inside the 14-day query period with the 1h window
let userWritable = @'(?i)^[a-z]:\\(users|programdata|windows\\temp|perflogs)\\';
// No legitimate reason to relay traffic or host a remote pipe. msbuild.exe has its own rules.
let unexpectedProcs = dynamic(["rundll32.exe", "regsvr32.exe", "mshta.exe", "installutil.exe",
    "regasm.exe", "regsvcs.exe", "werfault.exe", "notepad.exe", "searchprotocolhost.exe", "gpupdate.exe"]);
// dllhost.exe is only unexpected when started with no arguments (real COM surrogates always carry
// /Processid:{...}) or by something other than DcomLaunch (svchost) or COM+ System Application (services)
let dllhostParents = dynamic(["svchost.exe", "services.exe"]);
// Never legitimately run without arguments (injection targets are often started bare)
let noArgProcs  = dynamic(["dllhost.exe", "rundll32.exe", "regsvr32.exe", "werfault.exe", "searchprotocolhost.exe"]);
let noArgsRegex = @'(?i)^"?[^"]*\.exe"?\s*$';
// Assumption: if endpoints browse through an explicit proxy, list its IPs here so traffic to it
// counts as internet-bound rather than internal
let explicitProxyIPs = dynamic([]);
let minFanOut          = 3;        // internal ip:port endpoints reached by one process alongside an internet connection
let maxDevicesWithProc = 5;        // a user-writable-path process only counts if this few devices run it
let proxyCandidates = materialize(
    DeviceNetworkEvents
    | where TimeGenerated between (startTime .. endTime)
    | where ActionType in ("InboundConnectionAccepted", "ConnectionSuccess", "ConnectionAttempt", "ConnectionFailed")
    | where RemoteIPType in ("Private", "Public")
    | extend Proc = tolower(InitiatingProcessFileName), ParentProc = tolower(InitiatingProcessParentFileName),
             ProcPath = tolower(InitiatingProcessFolderPath)
    | extend NoArgs = Proc in (noArgProcs) and InitiatingProcessCommandLine matches regex noArgsRegex
    | extend IsUnexpected     = Proc in (unexpectedProcs)
                                or (Proc == "dllhost.exe" and (NoArgs or ParentProc !in (dllhostParents))),
             UserWritablePath = ProcPath matches regex userWritable
    | where IsUnexpected or UserWritablePath
    | extend Inbound  = ActionType == "InboundConnectionAccepted",
             External = RemoteIPType == "Public" or RemoteIP in (explicitProxyIPs)
    | extend InternalIn  = Inbound and RemoteIPType == "Private",
             InternalOut = not(Inbound) and not(External),
             ExternalOut = ActionType == "ConnectionSuccess" and External
    | summarize StartTime         = min(TimeGenerated),
                EndTime           = max(TimeGenerated),
                InboundIPs        = make_set_if(RemoteIP, InternalIn, 50),
                ListenPorts       = make_set_if(tostring(LocalPort), InternalIn, 10),
                InternalOutIPs    = make_set_if(RemoteIP, InternalOut, 50),
                InternalEndpoints = dcountif(strcat(RemoteIP, ":", tostring(RemotePort)), InternalOut),
                ExternalTargets   = dcountif(RemoteIP, ExternalOut),
                SampleTargets     = make_set_if(strcat(RemoteIP, ":", tostring(RemotePort)), not(Inbound), 25),
                SampleCommands    = make_set(InitiatingProcessCommandLine, 5)
        by DeviceId, DeviceName, Proc, ParentProc, ProcPath, Pid = InitiatingProcessId,
           AccountDomain = InitiatingProcessAccountDomain, AccountName = InitiatingProcessAccountName,
           IsUnexpected, UserWritablePath, NoArgs
    | extend InboundSources = array_length(InboundIPs),
             // internal hosts connected to that did not themselves connect in
             OnwardHosts    = array_length(set_difference(InternalOutIPs, InboundIPs))
    | extend Relay = InboundSources > 0 and (ExternalTargets > 0 or OnwardHosts > 0),
             Pivot = ExternalTargets > 0 and InternalEndpoints >= minFanOut
    | where Relay or Pivot);
// How many devices run each user-writable-path candidate (only checks the names found above, to keep it cheap)
let procPrevalence =
    DeviceNetworkEvents
    | where TimeGenerated between ((startTime - baselinePeriod) .. endTime)
    | where InitiatingProcessFileName in~ ((proxyCandidates | where not(IsUnexpected) | distinct Proc))
    | summarize DevicesWithProc = dcount(DeviceId) by Proc = tolower(InitiatingProcessFileName);
let proxyProc =
    proxyCandidates
    | join kind=leftouter procPrevalence on Proc
    | where IsUnexpected or DevicesWithProc <= maxDevicesWithProc
    | extend Reasons = array_concat(
            pack_array(strcat(Proc, " (parent ", ParentProc, ") accepted connections from ", InboundSources,
                              " internal host(s), reached ", InternalEndpoints, " internal endpoint(s) and ",
                              ExternalTargets, " internet host(s)")),
            iff(Relay, pack_array(strcat("Relay pattern: listening on port(s) ", strcat_array(ListenPorts, ","),
                                         " with onward connections")), dynamic([])),
            iff(Pivot, pack_array("Pivot pattern: internet connection plus internal fan-out from one process"), dynamic([])),
            iff(UserWritablePath, pack_array("Runs from a user-writable path"), dynamic([])),
            iff(NoArgs, pack_array("Process started with no arguments"), dynamic([])),
            iff(isnotnull(DevicesWithProc),
                pack_array(strcat("Process name seen on ", DevicesWithProc, " device(s) in ",
                                  toint(baselinePeriod / 1d), " days")), dynamic([])))
    | extend Severity = iff(IsUnexpected or (Relay and ExternalTargets > 0), "High", "Medium"),
             DistinctTargets = InternalEndpoints + ExternalTargets,
             Processes = pack_array(Proc),
             ParentProcesses = pack_array(ParentProc),
             DetectionBranch = "Proxy process";
proxyProc
| extend ReasonsText   = strcat_array(Reasons, "; "),
         SampleCommand = tostring(SampleCommands[0])
| project StartTime, EndTime, DeviceName, DeviceId, AccountDomain, AccountName,
          DetectionBranch, Severity, ReasonsText, DistinctTargets, SampleTargets,
          Processes, ParentProcesses, SampleCommand, SampleCommands
| order by StartTime desc

// T1090.001 Internal Proxy - C2 named pipe: default peer-to-peer C2 pipe names (SMB beacon style), or a
// remotely reachable pipe created by a process that shouldn't host one
// Runs hourly; window ends 10 minutes ago to allow for Defender ingestion delay.
let startTime = ago(70m);
let endTime   = ago(10m);
// Testing: uncomment, set dates (UTC), comment out the two lines above
// let startTime = datetime(2026-10-01 14:00:00);
// let endTime   = datetime(2026-10-01 17:00:00);
// No legitimate reason to relay traffic or host a remote pipe. msbuild.exe has its own rules.
let unexpectedProcs = dynamic(["rundll32.exe", "regsvr32.exe", "mshta.exe", "installutil.exe",
    "regasm.exe", "regsvcs.exe", "werfault.exe", "notepad.exe", "searchprotocolhost.exe", "gpupdate.exe"]);
// dllhost.exe is only unexpected when started with no arguments (real COM surrogates always carry
// /Processid:{...}) or by something other than DcomLaunch (svchost) or COM+ System Application (services)
let dllhostParents = dynamic(["svchost.exe", "services.exe"]);
// Never legitimately run without arguments (injection targets are often started bare)
let noArgProcs  = dynamic(["dllhost.exe", "rundll32.exe", "regsvr32.exe", "werfault.exe", "searchprotocolhost.exe"]);
let noArgsRegex = @'(?i)^"?[^"]*\.exe"?\s*$';
// Cobalt Strike defaults and common profile look-alikes, Covenant, PoshC2, Brute Ratel
let c2PipeRegex = @'(?i)\\(msagent_[0-9a-f]{2,}|msse-[0-9a-f]{3,}-server|postex_(ssh_)?[0-9a-f]{4}|status_[0-9a-f]{2}|(samr|netlogon|wkssvc|srvsvc|lsarpc|spoolss|ntsvcs|scerpc|interprocess)_[0-9a-f]{2,}|gruntsvc|jaccdpqnvbrrxlaf|demoagent_[0-9a-f]{2})$';
// SolarWinds Orion server name(s), from the DetectionExclusions watchlist - the short host name is
// enough. No rows = exclusion off.
let orionServers =
    _GetWatchlist('DetectionExclusions')
    | where Rule == "T1090.001" and ExceptionType == "OrionServer"
    | project DeviceName = tolower(tostring(SearchKey));
let c2Pipe =
    DeviceEvents
    | where TimeGenerated between (startTime .. endTime)
    | where ActionType == "NamedPipeEvent"
    | extend Fields = parse_json(AdditionalFields)
    | extend PipeName      = tostring(Fields.PipeName),
             FileOperation = tostring(Fields.FileOperation),
             RemoteAccess  = tostring(Fields.RemoteClientsAccess),
             Proc = tolower(InitiatingProcessFileName), ParentProc = tolower(InitiatingProcessParentFileName)
    | extend NoArgs = Proc in (noArgProcs) and InitiatingProcessCommandLine matches regex noArgsRegex
    | extend KnownC2Pipe    = PipeName matches regex c2PipeRegex,
             UnexpectedHost = (Proc in (unexpectedProcs)
                               or (Proc == "dllhost.exe" and (NoArgs or ParentProc !in (dllhostParents))))
                              and FileOperation == "File created" and RemoteAccess == "AcceptRemote"
    | where KnownC2Pipe or UnexpectedHost
    // SolarWinds Orion PDF export: its HTML-to-PDF engine runs a Chromium worker under rundll32,
    // started by the Orion web console (w3wp.exe) or ExportToPdfCmd.exe. Only on the servers listed.
    | where not(DeviceName has_any (orionServers)
                and Proc == "rundll32.exe" and ParentProc in ("w3wp.exe", "exporttopdfcmd.exe")
                and InitiatingProcessCommandLine has "--no-sandbox")
    | summarize StartTime       = min(TimeGenerated),
                EndTime         = max(TimeGenerated),
                SampleTargets   = make_set(PipeName, 10),
                RemoteClients   = make_set_if(RemoteIP, isnotempty(RemoteIP), 10),
                SampleCommands  = make_set(InitiatingProcessCommandLine, 5),
                KnownC2Pipe     = max(toint(KnownC2Pipe)),
                UnexpectedHost  = max(toint(UnexpectedHost)),
                NoArgs          = max(toint(NoArgs))
        by DeviceId, DeviceName, Proc, ParentProc,
           AccountDomain = InitiatingProcessAccountDomain, AccountName = InitiatingProcessAccountName
    | extend Reasons = array_concat(
            iff(KnownC2Pipe == 1, pack_array("Pipe name matches a default C2 peer-to-peer pipe"), dynamic([])),
            iff(UnexpectedHost == 1, pack_array(strcat(Proc, " (parent ", ParentProc,
                                                       ") created a pipe that accepts remote clients")), dynamic([])),
            iff(NoArgs == 1, pack_array("Process started with no arguments"), dynamic([])),
            iff(array_length(RemoteClients) > 0,
                pack_array(strcat("Remote client(s): ", strcat_array(RemoteClients, ", "))), dynamic([])))
    | extend Severity = iff(KnownC2Pipe == 1 or NoArgs == 1, "High", "Medium"),
             DistinctTargets = array_length(SampleTargets),
             Processes = pack_array(Proc),
             ParentProcesses = pack_array(ParentProc),
             DetectionBranch = "C2 named pipe";
c2Pipe
| extend ReasonsText   = strcat_array(Reasons, "; "),
         SampleCommand = tostring(SampleCommands[0])
| project StartTime, EndTime, DeviceName, DeviceId, AccountDomain, AccountName,
          DetectionBranch, Severity, ReasonsText, DistinctTargets, SampleTargets,
          Processes, ParentProcesses, SampleCommand, SampleCommands
| order by StartTime desc
